def add(a, b):
    return a + b


def divide(a, b):
    if b == 0:
        return None
    return a / b


def parse_int(value):
    if value == "":
        return None
    return int(value)


def normalize_name(name):
    if name is None:
        return ""
    return name.strip().lower()
